INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donny Donut: Dokrats', 'Donny, Donno and Donna were invited to the ceremony of collaboration with Candy-Land and an other continent, Food-City. Everything was going perfect until a strange wizard, named Brook, enters the President''s Palace. He wants to conquer the world and shape it at his mind, with the power of the Dokrats Relics. These are ancient relics from an old civilization, the Dokrats. They are the ancestors of our heroes.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 265689 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
