INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('potato-sack-racing-simulator-2024', 274581, '2023-10-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7mmu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2lxp.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Potato Sack Racing Simulator 2024', 'I know what you are thinking, and yes, this game does feature the ability to fight grandparents, mugs, speakers and of course dirty tissues... Wait, this is a game about Potato Sack Racing? Umm.. Yeah there are like 4 levels about Potato Sack Racing out of the 17 levels... Phew, we almost forgot to make it have something to do with Potato Sack Racing! But now trust me bro, this game is the BEST Potato Sack Racing game to have ever been made! At least, from what we could find.. Yeah this is actually the first and only Potato Sack Racing game, it’s almost like it’s not a good idea to make a game about Potato Sack Racing, it’s pretty fun to say Potato Sack Racing. Potatooooo sack racingggggg!!!!' FROM games WHERE igdb_id = 274581 ON CONFLICT (game_id, language_code) DO NOTHING;
