INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Drill and Collect', 'Drill and Collect is a simulation game where players manage a mining operation. The core gameplay involves drilling to find resources like gold and gems. It incorporates idle mechanics, allowing for progress even when offline, and features a system for upgrading equipment to improve mining efficiency. The game is presented in a casual, management-style format.' FROM games WHERE igdb_id = 249681 ON CONFLICT (game_id, language_code) DO NOTHING;
