INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aker Fern: Rdzeń Szatrisa - The Shatris Core.', 'As Mikołaj Fern I have been travelling and experiencing many adventures along the way. I was considered an antagonist by most of people from that era. Over five hundred years have passed until I came back to live as Dan Tern. As him I will lead a certain story that never reached its definitive end.' FROM games WHERE igdb_id = 248671 ON CONFLICT (game_id, language_code) DO NOTHING;
