INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deadly Broadcast', 'Camera is ready. Batteries are full. So let the broadcast begin! Deadly Broadcast is a co-op Horror game that can be played with 1-4 player. As a Live Broadcast phenomenon, your goal is to both survive and reach the maximum number of instant views by broadcasting in abandoned and dangerous places.' FROM games WHERE igdb_id = 153878 ON CONFLICT (game_id, language_code) DO NOTHING;
