INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Baten Kaitos Origins', 'Players will have the opportunity to discover or rediscover the emotional journeys of the Baten Kaitos series, which features distinct card-based RPG systems that allow for split-second decisions that edge participants closer to victory. Players will take the role of a Guardian Spirit, guiding each game’s protagonist and their companions through their journey.' FROM games WHERE igdb_id = 236710 ON CONFLICT (game_id, language_code) DO NOTHING;
