INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dongeng Bayang Kulit', 'Dongeng Bayang Kulit is a turn-based RPG that is loosely based on Southeast Asian folklore. You play as the recently ship-less, Captain N''man and his mystical guide, Putri Matami as they travel in search for answers regarding a mysterious apparition that has taken to incessantly haunting N''man.' FROM games WHERE igdb_id = 239266 ON CONFLICT (game_id, language_code) DO NOTHING;
