INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bladerite: Retribution', 'Bladerite offers action game enthusiasts a unique opportunity to polishing gaming skills like never before on cross-platform. Not only can you earn rewards based on defeating opponents in each match, but you can also acquire upgradeable patterns that enhance your game experience. Immerse yourself in a world where the in-game economy is supported by cryptocurrency.' FROM games WHERE igdb_id = 284634 ON CONFLICT (game_id, language_code) DO NOTHING;
