INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('whispered-flight', 274738, '2023-11-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7c2x.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2m04.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Whispered Flight', 'Embark upon a whimsical voyage as a radiant sphere of luminescence, gracefully soaring over the placid waters of a lake cradled within the ancient boughs of a mystical woodland. In pursuit of ethereal lumens, gather your scores under the watchful eyes of the stars, whilst evading the malevolent dark skulls seeking to quench your luminous essence. With a trinity of cherished lives, navigate through the verdant whispers of the old trees, to the gentle cadence of tranquility that accompanies your flight. Delight in the quaint, animated tapestry of nature’s hues as you partake in a casual contest of valor with fellow wanderers upon the leaderboard, in this gentle ballet of light against the encroaching shadow.' FROM games WHERE igdb_id = 274738 ON CONFLICT (game_id, language_code) DO NOTHING;
