INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'D Laser', 'You are constantly flying from side to side and slowly climbing up. You turn every time you hit the sides of the screen. Your goal is to avoid being hit by the laser shooting from the top and take cover under the descending skydivers. Press a button to turn and hold a button to stay in place. If the laser hits you, it will push you down and you also descend slowly when you stay still.' FROM games WHERE igdb_id = 272186 ON CONFLICT (game_id, language_code) DO NOTHING;
