INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Revive & Prosper', 'A voxel automation game where you''ll enjoy deep technical challenges and detailed simulations. Extract resources, construct an advanced automated base using belts and smart water control, and manage complex production chains. Whether you prefer to chill and build at your own pace or ramp up the difficulty by facing off against enemies, the choice is yours. Revive the land and master resource management to build the ultimate spaceport and launch into the stars.' FROM games WHERE igdb_id = 238707 ON CONFLICT (game_id, language_code) DO NOTHING;
