INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lovejuiced!: Hi Neighbor, meet Gamer', 'Keita’s summer kicks off with a random game chat—just anonymous “bros” trading jokes and awkward confessions. But when he learns his whole party is actually a group of girls living next door, things spiral fast in a season of neighborly chaos, college camaraderie, and maybe... something more.' FROM games WHERE igdb_id = 392989 ON CONFLICT (game_id, language_code) DO NOTHING;
