INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Infinite Black 2', 'The Infinite Black 2 casts the player in the roll of a Captain managing a fleet of ships to hunt aliens, trade resources, loot treasures, and craft equipment. Join player-run corporations with friends to build shipyards, discover (and use) strange alien technology, and vie for territorial control. Test your mettle in a PvP Arena against other Captains, or declare yourself an Outcast Corporation, waging a never-ending intergalactic war against all who oppose you!' FROM games WHERE igdb_id = 221519 ON CONFLICT (game_id, language_code) DO NOTHING;
