INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The King of Fighters XIII: Global Match', 'The King of Fighters XIII: Global Match, a version of the game with rollback netcode, was announced at Evo Japan 2023 for PlayStation 4 and Nintendo Switch. Three open beta tests took place throughout 2023 and the game was released on consoles on November 16, 2023. On PC, unlike previous rollback netcode upgrades by developer Iron Galaxy, Global Match was ported by Safari Games and announced as a separate purchase with Steam Edition being delisted shortly after its February 20, 2025 release.' FROM games WHERE igdb_id = 261086 ON CONFLICT (game_id, language_code) DO NOTHING;
