INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Batsugun: Saturn Tribute Boosted', 'Batsugun is a vertical scrolling shooter arcade game released in 1993 by Toaplan. The game attracted attention for the large number of bullets shot by both enemies and allies. This led many games to adopt the same kind of play. Batsugun thus became the pioneer of the bullet hell genre. The “Special” version of the game was then released on home consoles. The Special version offers new features with a better sound.' FROM games WHERE igdb_id = 237684 ON CONFLICT (game_id, language_code) DO NOTHING;
