INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mademoiselle Kshatriya', 'A young shrine maiden and her friend got lost in her dreaming world on Brahmanism. According to Manusmriti, no woman is permitted into four Varnas. A woman is born to be in the same class as the untouchable class. But her destiny helps her with trying to deny the irrational black magic.' FROM games WHERE igdb_id = 367622 ON CONFLICT (game_id, language_code) DO NOTHING;
