INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ItsJustAStory', 'ItsJustAStory is a solo post-apocalyptic game, it''s a story about a doctor and a build-up to the production of the actual game. your goal is to stay alive and find the cure, you play through a series of events with tasks simple to complete. the main focus here is to get the story.' FROM games WHERE igdb_id = 251745 ON CONFLICT (game_id, language_code) DO NOTHING;
