INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('starsiege-deadzone--2', 251581, '2023-07-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6kns.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2c10.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starsiege: Deadzone', 'Starsiege: Deadzone is a multiplayer corridor extraction shooter set in a dark sci-fi universe where humanity is on the brink of extinction. As space mercenaries, known as Raiders, players will team up with two others to explore the derelict stations taken over by sentient AI. As a Raider, your goal is to extract valuable weapons and resources for your faction. Players will select their class and venture into procedurally generated ships making each match unique. Choose from three distinct classes, each with their own unique abilities and work together to overcome the ship''s deadly traps and defenses in order to escape. Beware of the other Raiders seeking the same riches.' FROM games WHERE igdb_id = 251581 ON CONFLICT (game_id, language_code) DO NOTHING;
