INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Usagi Shima', 'Usagi Shima is a relaxing, idle bunny collecting game. You’ve been tasked as caretaker of an abandoned island — as you decorate it over time, curious (but adorable!) bunny visitors start to appear! Buy toys, plants, and build structures on an abandoned island to entice curious bun tourists to pay your island a visit. Discover, take photos, and make friends with a variety of bunnies that visit based on how you’ve decorated and arranged the island.' FROM games WHERE igdb_id = 204511 ON CONFLICT (game_id, language_code) DO NOTHING;
