INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panel Room', 'You are trapped in a certain place. Solve puzzles, find the exit, and escape. This game is different from ordinary escape games; in this one, you aim to escape by uncovering the rules of the room. You may not understand anything at first, but as you progress through the game, the overall picture of the room will gradually become clear. Aim to escape as you gradually understand the rules of the room.' FROM games WHERE igdb_id = 392688 ON CONFLICT (game_id, language_code) DO NOTHING;
