INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wandering Sword', 'Wandering Sword is a Wuxia-style pixel RPG. Play as a young man from Liao City in the Outer Lands who is accidentally drawn into a feud between two rival sects. Being in the wrong place at a wrong time results in getting poisoned with the lethal Frozen Toad. However, you are fortunate enough to have Qingxu, Sect Leader of Wudang, come to your aid and save your life. This is your turning point: the moment you decide to become a great warrior and enter the land of the Central Plains.' FROM games WHERE igdb_id = 202696 ON CONFLICT (game_id, language_code) DO NOTHING;
