INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('barton-lynch-pro-surfing', 272292, '2023-11-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7f0m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2md7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barton Lynch Pro Surfing', 'Barton Lynch Pro Surfing pits you against the world''s best surfer''s at the most exotic locations on the planet. More speed = more moves! Pump control uses the wave''s power so you can surf faster and unlock more tricks. BL Pro Surfing features 12 world famous locations from point-breaks, to beach-breaks or deep water reefs. An in-depth leader-board sports game played out over an expansive world tour, or if you prefer just cruise the open world locations. Cutting edge graphics meets hardcore physics & at times, beautifully brutal waves. Pump, smash that lip, get sooo barreled and launch airs from waves that barrel, peak, break left, right, or just foam crumble. Customize your own character to within an inch of your life, or, play as some of today''s top pros including: Yago Dora, Clay Marzo, Nathan Florence, Soli Bailey, Mahina Maeda, Vahine Fierro, Felicity Palmateer, and of course the legendary world champion, and Pro Surfing commentator Barton Lynch.' FROM games WHERE igdb_id = 272292 ON CONFLICT (game_id, language_code) DO NOTHING;
