INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skull Island: Rise of Kong - Colossal Edition', 'This edition includes 8 exclusive film grains featuring the ability to experience a red-tinted rage mode and the original look of the classic 1933 and 1970s era King Kong films, the Kong style pack with 8 different colors so you can choose-your-own Kong color, a boss-rush mode allowing you to defeat all the titans of Skull Island, and a behind-the-scenes exclusive pack including looks at in-game artwork and the all-original orchestral soundtrack.' FROM games WHERE igdb_id = 269382 ON CONFLICT (game_id, language_code) DO NOTHING;
