INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('too-bouncy', 263340, '2023-08-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co70e9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sco4lw.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Too Bouncy?', 'It''s a 2D pixel art game where you have to move a ball toward an exit point while collecting as many gems as possible. To move the box you need to push it with a box using your mouse or by touching your screen if you play on mobile. At the end of a level you will get a ranking from 1 to 3 stars. You''ll be scored on time too. To unlock the next level you have to get at least a one star rating.' FROM games WHERE igdb_id = 263340 ON CONFLICT (game_id, language_code) DO NOTHING;
