INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Wingman: Frontline 59', 'Project Wingman: Frontline 59 immerses players in exhilarating aerial combat, putting them in the pilot’s seat of a war-ravaged Earth’s most advanced fighter jets—and challenging them to prove they have what it takes to become a true ace. Pilots can engage in intense dogfights and large-scale ground assaults across a variety of fast-paced, action-packed game modes and missions, and they will discover the pure adrenaline rush of dodging railguns and geothermal weapons, striking against mechanized fortresses, and skimming the ground with gatling guns and wing-mounted rocket launchers.' FROM games WHERE igdb_id = 270216 ON CONFLICT (game_id, language_code) DO NOTHING;
