INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Dose', 'Final Dose is an immersive stealth simulator game inspired by slasher horror movies. You are being pursued by a relentless AI that can see and hear you. You will need to explore every inch of an abandoned clinic and find items and puzzle pieces to unlock doors and crawl through vents. Run or hide under beds, in bathroom stalls and cabinets, crouch to move around silently, and do whatever it takes to figure out how to escape this place!' FROM games WHERE igdb_id = 239831 ON CONFLICT (game_id, language_code) DO NOTHING;
