INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmic Salvage', 'Embark on an interstellar journey in ''Cosmic Salvage,'' a thrilling 2D platformer game made in Unity. Become the intrepid astronaut who crash-lands on an enigmatic and treacherous alien planet. Stranded far from home, you must navigate through perilous landscapes and cunning adversaries to retrieve the vital components needed to reignite your plasma engine.' FROM games WHERE igdb_id = 259305 ON CONFLICT (game_id, language_code) DO NOTHING;
