INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Confabulation', 'Your memory is fading. Things around your home keep changing; they are not what they appear to be. Find what is wrong, take pictures to restore your memory. Try to remember. Learn what you have forgotten, learn what has happened. It is not what it seems to be.' FROM games WHERE igdb_id = 231171 ON CONFLICT (game_id, language_code) DO NOTHING;
