INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('im-on-observation-duty-6', 254443, '2023-09-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co979i.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2eyf.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I''m on Observation Duty 6', 'The most ambitious I''m on Observation Duty game yet with six unique levels. Gameplay is familiar to those who have played the previous games. The game is part of a series of popular "spot the difference" -type of horror games. In I''m on Observation Duty 6 the players job is to monitor live surveillance camera footage and spot anomalies in the monitored rooms. You can swap between different camera-views. An anomaly means that for example something (e.g. a piece of furniture) has moved, an extra object has appeared or something has disappeared. There''s also scary intruders. When you notice something is different in any of the monitored rooms you have to file a report by clicking on the anomaly or choosing the right location and type of the anomaly from a menu to fix it. Anoamalies appear at random so the player never knows what is going to hapen next. Too many active and unreported anomalies means game over. Goal is to survive long enough (from 00:00 to 06:00 in game time). You will need sharp eyes and good memory to survive the entire night. The game contains psychological horror that mainly comes from making the player paranoid about what has changed in the house. There are also some scary monsters that might appear.' FROM games WHERE igdb_id = 254443 ON CONFLICT (game_id, language_code) DO NOTHING;
