INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('ahanar', 351293, '2023-05-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa1m1.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3vex.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ahanar', 'Ahanar is an interactive experience about a fictional (hopefully) town in Buryatia where all men were mobilized and none came back. Now Russia sends random men there and the women aren''t having it. This is a 40-60 minute experience intended to play in one sitting. It is an anti-war project and as such deals with hard topics of oppression, racism, warmongering, power abuse, homophobia.' FROM games WHERE igdb_id = 351293 ON CONFLICT (game_id, language_code) DO NOTHING;
