INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tristia: Legacy', '20 years after its initial release on PC in July 2002, Kogado Studio’s simulation game makes its debut on Switch. While the graphics have been overhauled for the modern era, Eeji Komatsu’s cute and sexy illustrations live on. Experience the origin story and roots of the long-running Tristia series.' FROM games WHERE igdb_id = 231522 ON CONFLICT (game_id, language_code) DO NOTHING;
