INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('garbage-crew', 179426, '2023-12-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co47pu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1hkm.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Garbage Crew!', 'Garbage Crew! is a game about chaos! You work in a team with two to four players and an angry garbage truck driver. Your job is to empty garbage cans and containers. Sadly, your contract doesn''t state what kind of work you are required to do, so your boss loads you with all kinds of extra tasks, including firefighting and forest work. Naturally you are completely understaffed, and your short-tempered driver has no intention of stopping the truck to wait for you, just because you couldn''t empty all the garbage cans while extinguishing a raging wildfire. Luckily, there are heaps of powerups that help you with all those tasks, so your stress level won''t reach dangerous heights... Or so you thought! Due to an accident in your bosses DIY time reverting device, you travel back into medieval times with seemingly no way to return and to make matters worse, your contract states that you are still required to work! So better get yourself a sword because the town is in the middle of a siege!' FROM games WHERE igdb_id = 179426 ON CONFLICT (game_id, language_code) DO NOTHING;
