INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Neon Heist: Cyber Drive chase', 'Welcome to the world of "Neon Heist: Cyber Drive chase" - an exciting arcade race in the style of cyberpunk, where adrenaline and drift are combined with an endless chase from the police. In this exciting game you have to enter a dangerous race for freedom, on the sparkling streets of a neon city.
