INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Harvest Havoc', 'A mix of farming and slapstick combat, Harvest Havoc is a chaotic multiplayer PvP party game for 2-6 players. Grow, harvest, (steal) and sell your crops to win! Fight with your fists or grow some weapons to smack your rivals and take their crops. Gather your friends online and compete to become the best farmer-warrior!' FROM games WHERE igdb_id = 276664 ON CONFLICT (game_id, language_code) DO NOTHING;
