INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zerlizan: The shadow of crime', 'On a barren planet, lacking resources and marked by harsh living conditions, you find yourself in the role of a young intelligence officer on the outskirts of civilization. In a disciplined society, rooted in a feudalistic system of government and deeply committed to the concept of honor, you are assigned the mission to investigate a possible murder in a impoverished and desertic village...' FROM games WHERE igdb_id = 289603 ON CONFLICT (game_id, language_code) DO NOTHING;
